      "视频号": ["视频号", "微信", "wx", "小程序", "微信小店", "微信视频号"],
      "线下": ["线下", "附近", "门店", "专卖店", "直营店", "实体店", "超市", "商店", "商场", "卖场", "苏宁", "国美", "五星", "重百", "门店在哪", "线下店", "体验店", "专柜", "经销商", "经销商网点", "就近", "现场", "去店里"]
    },
    "channel_definitions": {
